table.viewSql:
SELECT def.ad_org_id,
   def.ad_client_id,
   def.c_bpartner_id,
   def.c_doctype_id,
   def.c_region_id,
   def.description AS taxdef_desc,
   def.lbr_bpartnercategory_id,
   def.lbr_fiscalgroup_bpartner_id,
   def.lbr_fiscalgroup_product_id,
   def.lbr_legalmessage_id AS taxdef_message,
   def.lbr_ncm_id,
   def.lbr_productcategory_id,
   def.lbr_taxdefinition_id,
   def.lbr_tax_id,
   def.m_product_id,
   def.to_region_id_bkp AS to_region_id,
   def.lbr_issubtributaria,
   def.lbr_transactiontype,
   def.validfrom,
   def.priorityno,
   def.issotrx,
   def.lbr_cfop_id,
   def.cof_taxregimecode,
   def.cof_taxregimecodebp,
   def.cof_taxincentive,
   def.lbr_productsource_bkp AS lbr_productsource,
   def.cof_indie,
   def.ismanual AS taxdef_manual,
   def.value,
   def.cof_taxdefinition_group_id,
   def.c_city_id,
   def.cof_cityto_id,
   tax.description AS tax_desc,
   linha.lbr_taxrate,
   linha.lbr_taxbase,
   linha.lbr_taxamt,
   linha.lbr_taxname_id,
   linha.lbr_taxbaseamt,
   linha.istaxincluded,
   linha.lbr_legalmessage_id AS taxline_message,
   linha.lbr_taxstatus_id,
   linha.ismanual AS taxline_manual,
   linha.cof_overridetaxrate,
   linha.cof_overridetaxstatus,
   linha.cof_overridetaxlm,
   linha.cof_modbc_id,
   linha.cof_overridemodbc,
   linha.cof_overridelistamt,
   linha.cof_overridemvarate,
   linha.cof_mvarate,
   linha.cof_listamt,
   linha.cof_printondelivery,
   linha.cof_taxstatusdelivery_id,
   linha.cof_cenq_id,
   linha.cof_overridecenq,
   linha.lbr_formula_id,
   linha.cof_overrideformula,
   linha.cof_cnpjprod,
   linha.cof_vdespadu,
   linha.cof_viof,
   linha.cof_siscomexamt,
   linha.cof_overridemotdeson,
   linha.cof_overridedesonrate,
   linha.cof_desonrate,
   linha.cof_desonamt,
   linha.cof_motdeson_id,
   linha.cof_overridedifrate,
   linha.cof_difrate,
   linha.cof_difamt
  FROM ((lbr_taxdefinition def
    LEFT JOIN lbr_tax tax ON ((tax.lbr_tax_id = def.lbr_tax_id)))
    LEFT JOIN lbr_taxline linha ON ((linha.lbr_tax_id = tax.lbr_tax_id)));
